import { useEffect, useState } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import remarkSlug from 'remark-slug';
import rehypeRaw from 'rehype-raw';
import rehypeSanitize from 'rehype-sanitize';
import rehypeHighlight from 'rehype-highlight';

// Renders a Markdown document from a remote URL (e.g., raw.githubusercontent.com)
export default function MarkdownPage({ src }) {
  const [md, setMd] = useState('Loading...');

  // Convert GitHub blob URLs to raw URLs for direct content access
  const toRawIfGithubBlob = (url) => {
    try {
      const u = new URL(url);
      if (u.hostname === 'github.com') {
        const parts = u.pathname.split('/');
        // Expected: /<owner>/<repo>/blob/<branch>/<path...>
        const blobIndex = parts.indexOf('blob');
        if (blobIndex !== -1 && parts.length > blobIndex + 1) {
          const owner = parts[1];
          const repo = parts[2];
          const branch = parts[blobIndex + 1];
          const filePath = parts.slice(blobIndex + 2).join('/');
          return `https://raw.githubusercontent.com/${owner}/${repo}/${branch}/${filePath}`;
        }
      }
    } catch {}
    return url;
  };

  const resolvedSrc = toRawIfGithubBlob(src);

  useEffect(() => {
    let active = true;
    async function load() {
      try {
        const res = await fetch(resolvedSrc, { cache: 'no-store' });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const text = await res.text();
        if (active) setMd(text);
      } catch (e) {
        if (active) setMd(`# Failed to load markdown\n\nSource: ${resolvedSrc}`);
      }
    }
    load();
    return () => {
      active = false;
    };
  }, [resolvedSrc]);

  // After markdown renders, if there's a hash in the URL, scroll to that element
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const findTarget = (rawId) => {
      const candidates = [];
      const decoded = decodeURIComponent(rawId || '');
      candidates.push(decoded);
      candidates.push(decoded.replace(/_/g, '-'));
      candidates.push(decoded.toLowerCase());
      candidates.push(decoded.replace(/_/g, '-').toLowerCase());
      // Try each candidate as id or name
      for (const c of candidates) {
        const byId = document.getElementById(c);
        if (byId) return byId;
        const byName = document.querySelector(`[name="${c}"]`);
        if (byName) return byName;
      }
      return null;
    };

    const scrollToHash = () => {
      const hash = window.location.hash;
      if (hash && hash.length > 1) {
        const id = hash.slice(1);
        const target = findTarget(id);
        if (target && typeof target.scrollIntoView === 'function') {
          setTimeout(() => target.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50);
        }
      }
    };

    // Initial scroll after markdown is rendered
    scrollToHash();

    // Handle subsequent hash changes (e.g., clicking anchor links)
    window.addEventListener('hashchange', scrollToHash);
    return () => window.removeEventListener('hashchange', scrollToHash);
  }, [md]);

  // Resolve relative links/images against the markdown source base URL
  const base = (() => {
    try {
      const u = new URL(resolvedSrc);
      const parts = u.pathname.split('/');
      parts.pop();
      u.pathname = parts.join('/') + '/';
      return u.toString();
    } catch {
      return resolvedSrc;
    }
  })();

  const resolveUrl = (href) => {
    try {
      // absolute or protocol-relative stays as is
      if (/^([a-z]+:)?\/\//i.test(href)) return href;
      return new URL(href, base).toString();
    } catch {
      return href;
    }
  };

  // Generate stable slug (dashes) and alias (underscores) for headings
  const toSlug = (text) => {
    const s = String(text || '')
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9\s-_]/g, '')
      .replace(/[\s_]+/g, '-')
      .replace(/-+/g, '-')
      .replace(/^-|-$/g, '');
    return s || 'section';
  };

  const HeadingWithAnchors = ({ level, children }) => {
    const extractText = (nodes) => {
      if (typeof nodes === 'string') return nodes;
      if (Array.isArray(nodes)) return nodes.map(extractText).join('');
      if (nodes && nodes.props && nodes.props.children) return extractText(nodes.props.children);
      return '';
    };
    const text = extractText(children);
    const id = toSlug(text);
    const nameAlias = id.replace(/-/g, '_');
    const Tag = `h${level}`;
    return (
      <Tag id={id}>
        {children}
        {/* alias named anchor to support underscore-style hashes */}
        <a name={nameAlias} />
      </Tag>
    );
  };

  return (
    <div style={{ padding: '16px', maxWidth: '900px', margin: '0 auto' }}>
      <ReactMarkdown
        remarkPlugins={[remarkGfm, remarkSlug]}
        rehypePlugins={[rehypeRaw, rehypeSanitize, rehypeHighlight]}
        components={{
          h1: (props) => <HeadingWithAnchors level={1} {...props} />,
          h2: (props) => <HeadingWithAnchors level={2} {...props} />,
          h3: (props) => <HeadingWithAnchors level={3} {...props} />,
          h4: (props) => <HeadingWithAnchors level={4} {...props} />,
          h5: (props) => <HeadingWithAnchors level={5} {...props} />,
          h6: (props) => <HeadingWithAnchors level={6} {...props} />,
          a: ({ node, href, ...props }) => {
            const h = href || '';
            // For intra-page anchors like #section1, do not rewrite or open new tab
            if (h.startsWith('#')) {
              return <a href={h} {...props} />;
            }
            return (
              <a href={resolveUrl(h)} target="_blank" rel="noopener noreferrer" {...props} />
            );
          },
          img: ({ node, src, alt, ...props }) => (
            // eslint-disable-next-line jsx-a11y/alt-text
            <img src={resolveUrl(src || '')} alt={alt} style={{ maxWidth: '100%' }} {...props} />
          ),
        }}
      >
        {md}
      </ReactMarkdown>
    </div>
  );
}
