//https://github.com/apps/utterances
import React, { useEffect, useRef } from 'react'


function Comments() {
  const containerRef = useRef(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Avoid duplicate insertion (React 18 StrictMode mounts effects twice in dev)
    if (container.querySelector('iframe.utterances-frame')) {
      return;
    }

    const script = document.createElement('script');
    script.src = 'https://utteranc.es/client.js';
    script.async = true;
    script.setAttribute('repo', 'irfanhasib0/blogs');
    script.setAttribute('issue-term', 'url'); // or 'pathname'
    script.setAttribute('label', 'comment');
    script.setAttribute('theme', 'github-light');
    script.setAttribute('crossorigin', 'anonymous');

    container.appendChild(script);

    return () => {
      // Remove only the injected iframe/widgets; keep script removal to avoid timing issues
      container.querySelectorAll('iframe.utterances-frame').forEach((el) => el.remove());
      container.querySelectorAll('.utterances').forEach((el) => el.remove());
    };
  }, []);

  return (
    <div ref={containerRef} />
  );
}
export default Comments;
