import React from 'react';
import ReactDOM from 'react-dom/client';
import {BrowserRouter as Router,Routes, Route, Link, useParams} from 'react-router-dom';
import './index.css';
import App from './App';
import reportWebVitals from './reportWebVitals';

const root = ReactDOM.createRoot(document.getElementById('root'));
let defaultTopic = 'rcnn'
if (sessionStorage.getItem('topic')) {defaultTopic = sessionStorage.getItem('topic')}
const data      = require('./config.json')
const keys = Object.keys(data.topics)
const urls = keys.map((item,index)=> (<Route key={item} path={"/"+item+"/"} element={<App topic={item}/>}/>))

// Dynamic route wrapper to support any /blogs/:topic/* path
function RoutedApp() {
  const { topic } = useParams();
  const t = topic || 'rcnn';
  return <App topic={t} />;
}
//for (const key in Object.keys(data.topics])){
//    keys.push(key)
    
//}
console.log(defaultTopic)
root.render(
  <React.StrictMode> 
  <Router basename="/blogs">
    <Routes>
      {urls}
      <Route path="/" element={<App topic={'rcnn'}/>} />
      <Route path=":topic/*" element={<RoutedApp />} />
      <Route path="*" element={<App topic={'rcnn'} />} />
    </Routes>
    </Router>
  </React.StrictMode>
);


